22	// Dialer opens TLS connections along the path an https request would take. The
23	// zero value follows the proxy environment variables.
24	type Dialer struct {
25		// Proxy picks the proxy; nil means FromEnvironment.
26		Proxy Selector
27		// DialContext opens the TCP connection (to the proxy, or to the target when
28		// direct); nil means (&net.Dialer{}).DialContext.
29		DialContext func(ctx context.Context, network, addr string) (net.Conn, error)
30		// ProxyTLSConfig configures TLS to an https:// proxy; nil means system roots.
31		ProxyTLSConfig *tls.Config
32	}
33	
34	// DialTLS connects to hostport (the port is required) the way an https request
35	// to it would travel, then completes the handshake with cfg (ServerName
36	// defaults to the host). ctx bounds the whole: proxy dial, CONNECT, handshake.
37	//
38	// A failure of the proxy step is a *Error; a failure of the target itself (its
39	// handshake, its certificate) is returned as it would be without a proxy. The
40	// returned connection owns the tunnel: closing it closes the socket.
41	func (d Dialer) DialTLS(ctx context.Context, hostport string, cfg *tls.Config) (*tls.Conn, error) {
42		host, _, err := net.SplitHostPort(hostport)
43		if err != nil {
44			return nil, err
45		}
46		sel := d.Proxy
47		if sel == nil {
48			sel = FromEnvironment
49		}
50		proxy, err := sel(&url.URL{Scheme: "https", Host: hostport})
51		if err != nil {
52			return nil, &Error{Step: StepSelect, Err: err}
53		}
54		if proxy != nil && proxy.Scheme != "http" && proxy.Scheme != "https" {
55			return nil, &Error{Proxy: proxy.Host, Step: StepScheme, Err: errors.New(proxy.Scheme)}
56		}
57	
58		conn, err := d.tunnel(ctx, proxy, hostport)
59		if err != nil {
60			return nil, err
61		}
62	
63		tc := tls.Client(conn, targetConfig(cfg, host))
64		if err := tc.HandshakeContext(ctx); err != nil {
65			_ = conn.Close()
66			return nil, err
67		}
68		_ = conn.SetDeadline(time.Time{})
69		return tc, nil
70	}
