115	// connect runs TLS to the proxy when it is https://, then the CONNECT exchange,
116	// on conn. It closes conn on failure.
117	func (d Dialer) connect(ctx context.Context, conn net.Conn, proxy *url.URL, addr, hostport string) (net.Conn, *Error) {
118		fail := func(step Step, status int, err error) (net.Conn, *Error) {
119			_ = conn.Close()
120			if errors.Is(err, net.ErrClosed) && ctx.Err() != nil {
121				err = ctx.Err() // our own AfterFunc closed it: the cause is the context's
122			}
123			return nil, &Error{Proxy: addr, Step: step, StatusCode: status, Err: err}
124		}
125	
126		if proxy.Scheme == "https" {
127			cfg := &tls.Config{}
128			if d.ProxyTLSConfig != nil {
129				cfg = d.ProxyTLSConfig.Clone()
130			}
131			if cfg.ServerName == "" {
132				cfg.ServerName = proxy.Hostname()
133			}
134			tc := tls.Client(conn, cfg)
135			if err := tc.HandshakeContext(ctx); err != nil {
136				return fail(StepProxyTLS, 0, err)
137			}
138			conn = tc
139		}
140	
141		if _, err := io.WriteString(conn, connectRequest(proxy.User, hostport)); err != nil {
142			return fail(StepConnect, 0, err)
143		}
144		br := bufio.NewReader(io.LimitReader(conn, maxConnectAnswer))
145		resp, err := http.ReadResponse(br, &http.Request{Method: http.MethodConnect})
146		if err != nil {
147			return fail(StepConnect, 0, err)
148		}
149		// The body of a CONNECT answer is the tunnel; it is not read or closed here.
150		if resp.StatusCode != http.StatusOK {
151			return fail(StepConnect, resp.StatusCode, nil)
152		}
153		if n := br.Buffered(); n > 0 {
154			// Bytes read past the header belong to the tunnel; give them back first.
155			peeked, _ := br.Peek(n)
156			return &bufferedConn{Conn: conn, r: io.MultiReader(bytes.NewReader(bytes.Clone(peeked)), conn)}, nil
157		}
158		return conn, nil
159	}
